// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address to0, address to1, uint256 v) public {
        vm.assume(to0 != address(0));
        vm.assume(to1 != to0);
        address[] memory tos = new address[](2);
        tos[0] = to0;
        tos[1] = to1;
        bool ok = c.transfer(from, caddress, tos, v);
        assertTrue(ok);
    }
}
